import json,os,signal,sys
from pathlib import Path
def identity():
    fields=Path('/proc/self/stat').read_text().rsplit(')',1)[1].split()
    return {'pid':os.getpid(),'linux_start_ticks':int(fields[19])}
print(json.dumps({'event':'before_stop','process_identity':identity()}),flush=True)
os.kill(os.getpid(),signal.SIGSTOP)
print(json.dumps({'event':'after_continue','process_identity':identity()}),flush=True)
if sys.stdin.readline()!='exit\n':raise RuntimeError('missing owned parent release')
